#!/usr/bin/env bash
# Question 1: Control plane after maintenance. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "ops" >/dev/null 2>&1 || kubectl get namespace "ops" >/dev/null
timeout 60 bash -c "until kubectl -n 'ops' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ops
spec:
  replicas: 0
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF

(
case "${Q1_FAULT}" in
  scheduler-command)
    sed -i -E 's#^([[:space:]]*)- kube-scheduler$#\1- kube-schedular#' /etc/kubernetes/manifests/kube-scheduler.yaml
    grep -qE -- '- kube-schedular$' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-scheduler.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  controller-manager-kubeconfig)
    sed -i -E 's#^([[:space:]]*- --kubeconfig=/etc/kubernetes/controller-manager)\.conf$#\1.config#' /etc/kubernetes/manifests/kube-controller-manager.yaml
    grep -qE -- '- --kubeconfig=/etc/kubernetes/controller-manager.config$' /etc/kubernetes/manifests/kube-controller-manager.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-controller-manager.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-controller-manager is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  scheduler-kubeconfig-path)
    sed -i -E 's#^([[:space:]]*- --kubeconfig=/etc/kubernetes/scheduler)\.conf$#\1.config#' /etc/kubernetes/manifests/kube-scheduler.yaml
    grep -qE -- '- --kubeconfig=/etc/kubernetes/scheduler.config$' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-scheduler.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  scheduler-image-tag)
    grep -oE 'kube-scheduler:[^[:space:]"]+' /etc/kubernetes/manifests/kube-scheduler.yaml | head -1 > "/var/tmp/cka-q1.scheduler-image"
    sed -i -E 's#^([[:space:]]*image: [^[:space:]]*kube-scheduler:)[^[:space:]]+$#\1v0.0.0#' /etc/kubernetes/manifests/kube-scheduler.yaml
    grep -qE -- 'kube-scheduler:v0\.0\.0$' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-scheduler.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  controller-manager-sa-key)
    sed -i -E 's#^([[:space:]]*- --service-account-private-key-file=/etc/kubernetes/pki/sa)\.key$#\1.pem#' /etc/kubernetes/manifests/kube-controller-manager.yaml
    grep -qE -- '- --service-account-private-key-file=/etc/kubernetes/pki/sa.pem$' /etc/kubernetes/manifests/kube-controller-manager.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-controller-manager.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-controller-manager is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  scheduler-manifest-removed)
    mv /etc/kubernetes/manifests/kube-scheduler.yaml /var/tmp/cka-kube-scheduler.yaml
    [[ ! -f /etc/kubernetes/manifests/kube-scheduler.yaml ]]
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  scheduler-manifest-yaml)
    sed -i -E 's#^    image: (registry\.k8s\.io/kube-scheduler:)#   image: \1#' /etc/kubernetes/manifests/kube-scheduler.yaml
    grep -qE -- '^   image: registry.k8s.io/kube-scheduler:' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-scheduler.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  controller-manager-command)
    sed -i -E 's#^([[:space:]]*)- kube-controller-manager$#\1- kube-controller-managr#' /etc/kubernetes/manifests/kube-controller-manager.yaml
    grep -qE -- '- kube-controller-managr$' /etc/kubernetes/manifests/kube-controller-manager.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-controller-manager.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-controller-manager is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  scheduler-leader-elect)
    if grep -qE -- '- --config=' /etc/kubernetes/manifests/kube-scheduler.yaml; then
      sed -i -E 's#^([[:space:]]*- --config=).*$#\1/etc/kubernetes/sched-config.yaml#' /etc/kubernetes/manifests/kube-scheduler.yaml
    grep -qE -- '- --config=/etc/kubernetes/sched-config\.yaml$' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-scheduler.yaml" >&2; exit 1; }
    else
      sed -i -E '/^[[:space:]]*- kube-scheduler$/a\    - --config=/etc/kubernetes/sched-config.yaml' /etc/kubernetes/manifests/kube-scheduler.yaml
      grep -qE -- '- --config=/etc/kubernetes/sched-config\.yaml$' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not set scheduler --config" >&2; exit 1; }
    fi
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "ops" scale deployment/web --replicas=2
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
